toad_implementation.code_blueprint:
canvas {
  size: 800px 950px;
  fill: #0E0B0B;
  font-family: "Crimson Text, serif";
}

>obsidian = #0E0B0B;
>bloodRed = #8B0000;
>arcaneGold = #D4AF37;
>parchmentDim = #B5A48B;

rect #tomeBorder {
  at: center of canvas;
  size: 700px 850px;
  fill: #140E0E;
  stroke: >arcaneGold;
  stroke-width: 2px;
}

circle #magicCircleOuter {
  at: center of #tomeBorder offset 0px -120px;
  size: 320px;
  fill: none;
  stroke: >bloodRed;
  stroke-width: 3px;
}

circle #magicCircleInner {
  at: center of #magicCircleOuter;
  size: 260px;
  fill: alpha(>bloodRed, 0.28);
  stroke: >arcaneGold;
  stroke-width: 1px;
}

text #arcaneGlyph {
  at: center of #magicCircleInner;
  content: "☠";
  font-size: 72px;
  color: >arcaneGold;
}

text #spellName {
  at: below #magicCircleOuter offset 50px;
  content: "R I T U A L   O F   C H A O S";
  font-size: 28px;
  font-weight: 700;
  color: >arcaneGold;
}

text #spellMeta {
  at: below #spellName offset 12px;
  content: "LEVEL IX • TRANSMUTATION • CASTING: 1 HOUR";
  font-size: 12px;
  color: >parchmentDim;
}

rect #statsBox {
  at: below #spellMeta offset 32px;
  size: 580px 100px;
  fill: #1C1212;
  stroke: >bloodRed;
  stroke-width: 1px;
}

text #statsContent {
  at: center of #statsBox;
  size: 540px;
  content: "Target must succeed on a DC 19 Constitution saving throw or suffer 10d10 necrotic damage as flesh transforms into ash.";
  font-size: 14px;
  color: #D2C4B2;
}
